const DEFAULT_WEIGHT = W(2, 2);
export function weightInfo(id) {
  return WEIGHTAGE[id] || DEFAULT_WEIGHT;
}

export function weightLabel(id) {
  const { w, pyq } = weightInfo(id);
  return pyq ? `~${w} marks · ${pyq} PYQs/5yr` : `~${w} marks`;
}

export const SUBJECT_MAX_WEIGHT = Object.values(CONCEPTS)
  .reduce((m, c) => {
    m[c.subject] = (m[c.subject] || 0) + weightInfo(c.id).w;
    return m;
  }, {});
